const topicInput = $('Topic').first().json.topic;
// Safety check: if input is missing, default to "general"
const topic = topicInput ? topicInput.toLowerCase() : "general";

const items = $input.all();

// 1. Safety check: Handle empty RSS feed
if (!items || items.length === 0) {
  return []; 
}

// 2. FILTER: Find articles mentioning the topic
let relevantItems = items.filter(item => {
  const title = (item.json.title || "").toLowerCase();
  const content = (item.json.contentSnippet || "").toLowerCase();
  return title.includes(topic) || content.includes(topic);
});

// 3. FALLBACK: If no match, use the first item (safely)
if (relevantItems.length === 0) {
  relevantItems = [items[0]];
}

// 4. LIMIT: Return only 1 item
return relevantItems.slice(0, 1);

