// Get the raw output from the AI Agent
// Note: Depending on your Agent's settings, the text might be in 'output', 'text', or 'response'
const item = $input.item.json;
const rawText = item.output || item.text || item.response || JSON.stringify(item);

// 1. CLEAN: Remove Markdown (```json ... ```) and find the JSON object
// This regex looks for content specifically between the first '{' and the last '}'
let cleanText = rawText;
const firstBrace = rawText.indexOf('{');
const lastBrace = rawText.lastIndexOf('}');

if (firstBrace !== -1 && lastBrace !== -1) {
  cleanText = rawText.substring(firstBrace, lastBrace + 1);
}

// 2. PARSE: safely convert to JSON
let data = {};
try {
  data = JSON.parse(cleanText);
} catch (error) {
  // Fallback: If parsing fails, wrap the raw text so the workflow doesn't stop
  data = {
    hook: "Error parsing AI response",
    body: rawText.substring(0, 200) + "..." // truncate for safety
  };
}

// 3. RETURN: Map to the fields your Google Sheet expects
return {
  json: {
    hook: data.hook || data.Hook,
    body: data.body || data.Body
  }
};
